// Des: Async cloud sync: records to DB, pages as packs
// Flo: create cloud tables > send compact record rows in one batch (ledger of cloud bytes) > pack due raw files into 1 archive per run, upload, verify size, write manifest, mark done > any failure leaves rows queued with backoff and says which layer failed
// I/O: local Db + raw files + Store + Sql (caller) > cloud rows and runs/<date>.pack objects; Sres counts and layer flags
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const s3v4 = @import("sy-clou-s3v4.zig"); const cfgz = @import("cf-conf-load.zig"); const pack = @import("ru-purg-pack.zig");
const CF = .{ .maxp = 64 << 20, .rawd = "raw", .over = 200, .dayz = 86400000 };
pub const Vsto = struct { name: []const u8, store: stor.Stor };
pub const Vsql = struct { name: []const u8, sql2: sqlz.Sqlz };
pub const Sync = struct { iozz: std.Io, dbzz: *sqli.Dbzz, dirz: []const u8, conf: cfgz.Conf, store: stor.Stor, sql2: sqlz.Sqlz, copy: ?stor.Stor = null, vnam: []const u8 = "", pool: []const Vsto = &.{}, sqls: []const Vsql = &.{}, dryz: bool = false };
pub const Sres = struct { recs: u32 = 0, fil2: u32 = 0, pac2: u64 = 0, fail: u32 = 0, pack: []const u8 = "", lays: u8 = 0, veri: bool = false };
pub const LAYZ_STOR: u8 = 1;
pub const LAYZ_SQLZ: u8 = 2;
fn urlh(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { return aren.dupe(u8, &hash.hashHexz(urlz)); }
fn cutz(text: []const u8, maxz: u32) []const u8 { if (text.len <= maxz) return text; var endz: usize = maxz; while (endz > 0 and (text[endz] & 0xC0) == 0x80) endz -= 1; return text[0..endz]; }
fn numz(aren: std.mem.Allocator, valu: i64) ![]const u8 { return std.fmt.allocPrint(aren, "{d}", .{valu}); }
pub fn ledgSetz(dbzz: *sqli.Dbzz, urlk: []const u8, byts: i64) !void { var stmt = try dbzz.prep("INSERT INTO dbcl(urlh,byts) VALUES(?1,?2) ON CONFLICT(urlh) DO UPDATE SET byts=?2;"); defer stmt.fini(); try stmt.bindText(1, urlk); try stmt.bindIntz(2, byts); _ = try stmt.step(); }
pub fn ledgBack(self: *Sync, aren: std.mem.Allocator) !u32 { var flgz = try self.dbzz.prep("SELECT valu FROM flag WHERE name='ledg_back';"); defer flgz.fini(); if (try flgz.step()) { if (flgz.colzIntz(0) == 1) return 0; } var stmt = try self.dbzz.prep("SELECT urlz,length(body) FROM reco;"); defer stmt.fini(); const Rowz = struct { urlh: []const u8, byts: i64 }; var list: std.ArrayList(Rowz) = .empty; while (try stmt.step()) { const urlz = stmt.colzText(0); const lenz: i64 = @min(stmt.colzIntz(1), @as(i64, self.conf.clou_body_maxz)); try list.append(aren, .{ .urlh = try urlh(aren, urlz), .byts = @as(i64, @intCast(urlz.len)) + lenz + CF.over }); } for (list.items) |row2| { var insz = try self.dbzz.prep("INSERT OR IGNORE INTO dbcl(urlh,byts) VALUES(?1,?2);"); defer insz.fini(); try insz.bindText(1, row2.urlh); try insz.bindIntz(2, row2.byts); _ = try insz.step(); } var setz = try self.dbzz.prep("INSERT INTO flag(name,valu) VALUES('ledg_back',1) ON CONFLICT(name) DO UPDATE SET valu=1;"); defer setz.fini(); _ = try setz.step(); return @intCast(list.items.len); }
pub fn vendBack(self: *Sync, name: []const u8) !void { var stmt = try self.dbzz.prep("UPDATE pack SET vend=?1 WHERE vend='';"); defer stmt.fini(); try stmt.bindText(1, name); _ = try stmt.step(); }
pub fn goneSkip(self: *Sync, aren: std.mem.Allocator, urlz: []const u8, nowz: i64) !bool { const row2 = (try inde.pageGetz(self.dbzz, aren, urlz)) orelse return false; return (row2.code == 404 or row2.code == 410) and nowz - row2.fetc > @as(i64, self.conf.purg_dbzz_gone_days) * CF.dayz; }
pub fn reczStmt(self: *Sync, aren: std.mem.Allocator, urlz: []const u8, list: *std.ArrayList([]const u8)) !?i64 { const row2 = (try inde.pageGetz(self.dbzz, aren, urlz)) orelse return null; const recz = (try inde.recoGetz(self.dbzz, aren, urlz)) orelse return null; const dial = self.sql2.dial; const bodz = cutz(recz.body, self.conf.clou_body_maxz); const uhzz = try sqlz.litz(aren, dial, try urlh(aren, urlz)); const page = [_]sqlz.Colz{ .{ .name = "urlh", .valu = uhzz }, .{ .name = "urlz", .valu = try sqlz.litz(aren, dial, urlz) }, .{ .name = "hexz", .valu = try sqlz.litz(aren, dial, row2.hexz) }, .{ .name = "code", .valu = try numz(aren, row2.code) }, .{ .name = "tier", .valu = try numz(aren, row2.tier) }, .{ .name = "vend", .valu = try sqlz.litz(aren, dial, row2.vend) }, .{ .name = "fetc", .valu = try numz(aren, row2.fetc) } }; const reco = [_]sqlz.Colz{ .{ .name = "urlh", .valu = uhzz }, .{ .name = "hexz", .valu = try sqlz.litz(aren, dial, recz.hexz) }, .{ .name = "kind", .valu = try sqlz.litz(aren, dial, recz.kind) }, .{ .name = "body", .valu = try sqlz.litz(aren, dial, bodz) }, .{ .name = "timz", .valu = try numz(aren, row2.fetc) } }; try list.append(aren, try sqlz.upse(aren, dial, "cl_page", "urlh", &page)); try list.append(aren, try sqlz.upse(aren, dial, "cl_reco", "urlh", &reco)); return @as(i64, @intCast(urlz.len + bodz.len)) + CF.over; }
fn syncRecs(self: *Sync, aren: std.mem.Allocator, nowz: i64, rslt: *Sres) !void { const duez = try outb.outbDuez(self.dbzz, aren, "rec", nowz, self.conf.clou_sync_batz); if (duez.len == 0) return; var stmz: std.ArrayList([]const u8) = .empty; var good: std.ArrayList([]const u8) = .empty; var byts: std.ArrayList(i64) = .empty; for (duez) |item| { if (try goneSkip(self, aren, item.keyz, nowz)) { try outb.outbDone(self.dbzz, "rec", item.keyz); continue; } if (try reczStmt(self, aren, item.keyz, &stmz)) |sizz| { try good.append(aren, item.keyz); try byts.append(aren, sizz); } else try outb.outbDone(self.dbzz, "rec", item.keyz); } if (stmz.items.len == 0) return; self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items) catch |err3| { for (good.items) |urlz| try outb.outbFail(self.dbzz, "rec", urlz, @errorName(err3), nowz); rslt.fail += @intCast(good.items.len); rslt.lays |= LAYZ_SQLZ; return err3; }; for (good.items, 0..) |urlz, indx| { try ledgSetz(self.dbzz, try urlh(aren, urlz), byts.items[indx]); try outb.outbDone(self.dbzz, "rec", urlz); } rslt.recs += @intCast(good.items.len); }
fn vfyzPack(self: *Sync, aren: std.mem.Allocator, key2: []const u8, lenz: usize) bool { const objs = self.store.list(self.store.ctx2, aren, self.iozz, key2) catch return false; for (objs) |obj2| { if (std.mem.eql(u8, obj2.key2, key2) and obj2.size == lenz) return true; } return false; }
fn syncFile(self: *Sync, aren: std.mem.Allocator, nowz: i64, rslt: *Sres) !void { const duez = try outb.outbDuez(self.dbzz, aren, "file", nowz, self.conf.clou_sync_batz); if (duez.len == 0) return; var pars: std.ArrayList(pack.Part) = .empty; var size: usize = pack.CF.magi.len; const rawd = try std.fs.path.join(aren, &.{ self.dirz, CF.rawd }); for (duez) |item| { if (!hash.hashOkay(item.keyz)) { try outb.outbFail(self.dbzz, "file", item.keyz, "bad hash", nowz); continue; } var buff: [96]u8 = undefined; const rela = try hash.hashPath(&buff, item.keyz[0..64].*); const path = try std.fs.path.join(aren, &.{ rawd, rela }); const gzzz = std.Io.Dir.cwd().readFileAlloc(self.iozz, path, aren, .limited(CF.maxp)) catch { try outb.outbFail(self.dbzz, "file", item.keyz, "local file missing", nowz); rslt.fail += 1; continue; }; if (size + pack.CF.head + gzzz.len > CF.maxp) break; size += pack.CF.head + gzzz.len; try pars.append(aren, .{ .hexz = item.keyz, .gzzz = gzzz }); } if (pars.items.len == 0) return; const pac2 = try pack.packBuil(aren, pars.items); const ents = try pack.packPars(aren, pac2); const key2 = try pack.packName(aren, pack.CF.runs, nowz, pac2); self.store.put(self.store.ctx2, aren, self.iozz, key2, pac2) catch |err3| { for (pars.items) |part| try outb.outbFail(self.dbzz, "file", part.hexz, @errorName(err3), nowz); rslt.fail += @intCast(pars.items.len); rslt.lays |= LAYZ_STOR; return err3; }; const vfyn: i64 = if (vfyzPack(self, aren, key2, pac2.len)) nowz else 0; rslt.veri = vfyn > 0;
var stmz: std.ArrayList([]const u8) = .empty; for (ents) |entr| { const cols = [_]sqlz.Colz{ .{ .name = "hexz", .valu = try sqlz.litz(aren, self.sql2.dial, entr.hexz) }, .{ .name = "pack", .valu = try sqlz.litz(aren, self.sql2.dial, key2) }, .{ .name = "offs", .valu = try numz(aren, @intCast(entr.offs)) }, .{ .name = "lenz", .valu = try numz(aren, @intCast(entr.lenz)) } }; try stmz.append(aren, try sqlz.upse(aren, self.sql2.dial, "cl_manif", "hexz", &cols)); } self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items) catch |err3| { for (pars.items) |part| try outb.outbFail(self.dbzz, "file", part.hexz, @errorName(err3), nowz); rslt.fail += @intCast(pars.items.len); rslt.lays |= LAYZ_SQLZ; return err3; };
try self.dbzz.exec("BEGIN IMMEDIATE;"); errdefer self.dbzz.exec("ROLLBACK;") catch {}; for (ents) |entr| { var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz,vend) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(hexz) DO UPDATE SET packk=?2,offs=?3,lenz=?4,vfyz=?5,vend=?6;"); defer insz.fini(); try insz.bindText(1, entr.hexz); try insz.bindText(2, key2); try insz.bindIntz(3, @intCast(entr.offs)); try insz.bindIntz(4, @intCast(entr.lenz)); try insz.bindIntz(5, vfyn); try insz.bindText(6, self.vnam); _ = try insz.step(); try outb.outbDone(self.dbzz, "file", entr.hexz); } try self.dbzz.exec("COMMIT;"); rslt.fil2 += @intCast(ents.len); rslt.pac2 += pac2.len; rslt.pack = key2; }
pub fn syncRunx(self: *Sync, aren: std.mem.Allocator, nowz: i64, rslt: *Sres) !void { self.sql2.exec(self.sql2.ctx2, aren, self.iozz, &sqlz.DDL) catch |err3| { rslt.fail += 1; rslt.lays |= LAYZ_SQLZ; return err3; }; try syncRecs(self, aren, nowz, rslt); try syncFile(self, aren, nowz, rslt); }
pub fn syncRunz(self: *Sync, aren: std.mem.Allocator, nowz: i64) !Sres { var rslt: Sres = .{}; try syncRunx(self, aren, nowz, &rslt); return rslt; }
pub fn storOfzz(self: *Sync, vend: []const u8) stor.Stor { for (self.pool) |item| { if (std.mem.eql(u8, item.name, vend)) return item.store; } return self.store; }
pub fn res3(self: *Sync, aren: std.mem.Allocator, hexz: hash.Hexz) ![]u8 { var stmt = try self.dbzz.prep("SELECT packk,offs,lenz,vend FROM pack WHERE hexz=?1;"); defer stmt.fini(); try stmt.bindText(1, &hexz); if (!try stmt.step()) return error.NotFound; const key2 = try aren.dupe(u8, stmt.colzText(0)); const offs: usize = @intCast(stmt.colzIntz(1)); const lenz: usize = @intCast(stmt.colzIntz(2)); const sto2 = storOfzz(self, stmt.colzText(3)); const pac2 = sto2.get(sto2.ctx2, aren, self.iozz, key2) catch |err3| blkz: { const cop2 = self.copy orelse return err3; if (pack.packGenz(key2) != 1) return err3; break :blkz try cop2.get(cop2.ctx2, aren, self.iozz, key2); }; if (offs + lenz > pac2.len) return error.HashMismatch; const body = try file.gzipOpen(aren, pac2[offs .. offs + lenz], CF.maxp); const back = hash.hashHexz(body); if (!std.mem.eql(u8, &back, &hexz)) return error.HashMismatch; return body; }
